import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        Long first = null, second = null;
        for (int i = 0; i < n; i++) {
            long x = sc.nextLong();
            if (first == null || x > first) {
                if (first != null && x != first) second = first;
                first = x;
            } else if (x != first && (second == null || x > second)) {
                second = x;
            }
        }
        System.out.println(second == null ? "NONE" : second);
    }
}

